<?php
$rooms = $pdo->query(
    "SELECT rooms.*, (SELECT COUNT(*) FROM allocations WHERE allocations.room_id = rooms.id AND allocations.status = 'Active') AS occupied
     FROM rooms ORDER BY building, room_number"
)->fetchAll();
?>
<section class="page-heading-row"><div><span class="eyebrow">A PLACE TO CALL HOME</span><h1>Hostel rooms<span class="heading-dot">.</span></h1><p>Room details, occupancy, and availability at a glance.</p></div><span class="count-chip"><?= count($rooms) ?> rooms</span></section>
<?php if (in_array($role, ['admin', 'warden'], true)): ?><section class="panel form-panel"><div class="panel-heading"><div><span class="eyebrow">HOSTEL DIRECTORY</span><h2>Add a room</h2></div><span class="form-step">01 <i>/</i> room details</span></div>
<form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save_room"><input type="hidden" name="return_to" value="rooms">
<label class="form-field"><span>Room number</span><input name="room_number" required maxlength="30" placeholder="e.g. C-108"></label><label class="form-field"><span>Building / hostel</span><input name="building" required maxlength="100" placeholder="e.g. Maple House"></label><label class="form-field"><span>Capacity</span><input name="capacity" type="number" min="1" max="100" required placeholder="e.g. 3"></label><label class="form-field"><span>Room status</span><select name="status"><option>Active</option><option>Maintenance</option><option>Inactive</option></select></label><div class="form-submit-row"><span>Capacity is checked when allocating rooms.</span><button class="button button-primary" type="submit">Add room <span>→</span></button></div></form></section><?php endif; ?>
<section class="room-grid"><?php foreach ($rooms as $room): $available = (int) $room['capacity'] - (int) $room['occupied']; ?><article class="room-card <?= $room['status'] !== 'Active' ? 'room-card-muted' : '' ?>"><div class="room-card-top"><span class="room-building"><?= e($room['building']) ?></span><span class="room-status room-status-<?= strtolower(e($room['status'])) ?>"><i></i><?= e($room['status']) ?></span></div><div class="room-number">Room <b><?= e($room['room_number']) ?></b></div><div class="occupancy-row"><div><b><?= (int) $room['occupied'] ?></b><span> / <?= (int) $room['capacity'] ?> occupied</span></div><span><?= $available > 0 && $room['status'] === 'Active' ? $available . ' available' : 'At capacity' ?></span></div><div class="occupancy-track"><span style="width: <?= (int) min(100, round(((int) $room['occupied'] / max(1, (int) $room['capacity'])) * 100)) ?>%"></span></div><div class="room-card-bottom"><span><?= $room['status'] === 'Active' && $available > 0 ? '✦ Ready for allocation' : ($room['status'] === 'Active' ? 'Room is full' : 'Unavailable for allocation') ?></span><a href="index.php?view=allocations" aria-label="View allocations">↗</a></div></article><?php endforeach; ?>
<?php if (!$rooms): ?><div class="panel empty-state"><span class="empty-art">⌂</span><b>No rooms in the directory</b><p>Add a room to start managing hostel capacity.</p></div><?php endif; ?></section>
